'use strict';

// Serves the icon contact sheets generated by tools/icon-buckets.js together
// with the raw PNGs they reference.

const fs = require('fs');
const path = require('path');
const http = require('http');

const GC = process.argv[2] || path.join(
  process.env.APPDATA || '', 'QQEX', 'miniapp', 'fs', '2351686624', '1112386029', 'usr', 'gamecaches');
const OUT = process.argv[3] || path.join(__dirname, '..', 'artifacts', 'icon-sheet');
const PORT = Number(process.env.SHEET_PORT || 17899);

http.createServer(function (req, res) {
  const u = decodeURIComponent(req.url.split('?')[0]);
  if (u === '/') {
    const files = fs.readdirSync(OUT).filter(function (f) { return f.endsWith('.html'); });
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end('<meta charset="utf-8"><body style="background:#111;color:#ddd;font:14px monospace">' +
      files.map(function (f) { return '<div><a style="color:#8cf" href="/' + f + '">' + f + '</a></div>'; }).join('') +
      '</body>');
    return;
  }
  const m = /^\/img\/([^/]+)\/(.+)$/.exec(u);
  if (m) {
    const p = path.join(GC, m[1], m[2]);
    if (p.startsWith(GC) && fs.existsSync(p)) {
      res.writeHead(200, { 'Content-Type': 'image/png' });
      res.end(fs.readFileSync(p));
      return;
    }
  }
  const f = path.join(OUT, path.basename(u));
  if (f.startsWith(OUT) && fs.existsSync(f)) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(fs.readFileSync(f));
    return;
  }
  res.writeHead(404); res.end('nope');
}).listen(PORT, '127.0.0.1', function () {
  console.log('icon view: http://127.0.0.1:' + PORT + '/');
});
